-- ============================================================
-- Seed: reference data (teams, squads, current gameweek + fixtures)
-- Generated by scripts/generate-seed-sql.mjs — do not edit by hand.
-- Safe to re-run: upserts on primary key.
-- ============================================================

on conflict (id) do update set name = excluded.name, short_name = excluded.short_name, tla = excluded.tla, color = excluded.color, crest_url = excluded.crest_url;

on conflict (id) do update set team_id = excluded.team_id, name = excluded.name, position = excluded.position;

on conflict (id) do update set number = excluded.number, title = excluded.title, deadline = excluded.deadline, status = excluded.status;

on conflict (id) do update set gameweek_id = excluded.gameweek_id, home_team_id = excluded.home_team_id, away_team_id = excluded.away_team_id, kickoff_time = excluded.kickoff_time;

